// 伪代码：分层检索策略的简化编排，按代价从低到高逐级兜底
async function searchCode(query, repoPath) {
  // 第一级：关键词搜索，默认路径，零索引延迟，覆盖大多数场景
  const grepHits = await ripgrepSearch(query, repoPath);
  if (grepHits.length > 0) return grepHits;

  // 第二级：AST 结构化匹配，用于"查找某符号的所有引用"这类结构化查询
  const astHits = await treeSitterFindReferences(query, repoPath);
  if (astHits.length > 0) return astHits;

  // 第三级：向量检索，仅在前两级都没有命中时兜底，处理模糊语义查询
  return await vectorSearch(query, repoPath, { topK: 10 });
}

// LSP 只在需要精确定义/引用时按需调用，成本较高，不作为默认路径
async function resolveSymbolPrecisely(filePath, position) {
  const lsp = await getOrStartLanguageServer(filePath);
  return lsp.definition(filePath, position);
}

# 伪代码：简化的分支覆盖率插桩原理
coverage_counters = {}

def instrument(branch_id):
    # 每次对应分支入口被真正执行时，计数器 +1
    coverage_counters[branch_id] = coverage_counters.get(branch_id, 0) + 1

def check(x):
    if x > 0:
        instrument("check.true")   # 插桩点：真分支被执行
        return "positive"
    else:
        instrument("check.false")  # 插桩点：假分支被执行
        return "non-positive"

# 测试跑完后统计分支覆盖率
def branch_coverage(all_branches):
    hit = sum(1 for b in all_branches if coverage_counters.get(b, 0) > 0)
    return hit / len(all_branches)
